<header class="page-hero"><p class="eyebrow"><?= e($eyebrow ?? 'Let’s create') ?></p><h1><?= e($title) ?></h1><p class="lead"><?= e($intro ?? '') ?></p></header><section class="section container"><form method="post" enctype="multipart/form-data" class="form-grid" action="<?= e(url($action)) ?>"><?= csrf_field() ?><?php foreach ($fields as $field): ?><div class="field <?= !empty($field['full']) ? 'full' : '' ?>"><label for="<?= e($field['name']) ?>"><?= e($field['label']) ?><?= !empty($field['required']) ? ' *' : '' ?></label><?php if (($field['type'] ?? 'text') === 'textarea'): ?><textarea id="<?= e($field['name']) ?>" name="<?= e($field['name']) ?>" <?= !empty($field['required'])?'required':'' ?>><?= old($field['name']) ?></textarea><?php elseif (($field['type'] ?? '') === 'select'): ?><select id="<?= e($field['name']) ?>" name="<?= e($field['name']) ?>"><?php foreach ($field['options'] as $option): ?><option><?= e($option) ?></option><?php endforeach; ?></select><?php elseif (($field['type'] ?? '') === 'checkbox'): ?><label><input id="<?= e($field['name']) ?>" type="checkbox" name="<?= e($field['name']) ?>" value="1" required> <?= e($field['help'] ?? '') ?></label><?php else: ?><input id="<?= e($field['name']) ?>" type="<?= e($field['type'] ?? 'text') ?>" name="<?= e($field['name']) ?>" value="<?= ($field['type'] ?? '') === 'file' ? '' : old($field['name']) ?>" <?= !empty($field['required'])?'required':'' ?> <?= ($field['type'] ?? '') === 'file' ? 'accept="image/jpeg,image/png,image/webp"' : '' ?>><?php endif; ?></div><?php endforeach; ?><div class="field full"><button><?= e($submit ?? 'Send') ?></button></div></form></section>

